function renderConnectedDevicesTab(connectedDevices) {
    if (!connectedDevices || connectedDevices.length === 0) {
        return `
            <div class="alert alert-info">
                <i class="bi bi-info-circle"></i> Nenhum dispositivo conectado informado pelo CPE
            </div>
        `;
    }

    let html = '<h6><i class="bi bi-hdd-network"></i> Dispositivos conectados <span class="badge bg-primary">' + connectedDevices.length + '</span></h6>';

    html += `
        <div class="mb-3">
            <small class="text-muted" id="hotspot-status"><i class="bi bi-router"></i> Aguardando leitura de tráfego...</small>
        </div>
        <div class="table-responsive">
            <table class="table table-sm table-bordered table-hover" id="connected-devices-table">
                <thead class="table-light">
                    <tr>
                        <th width="4%" class="text-center">#</th>
                        <th width="18%"><i class="bi bi-pc-display"></i> Dispositivo</th>
                        <th width="12%"><i class="bi bi-hdd-network"></i> Endereço IP</th>
                        <th width="15%"><i class="bi bi-ethernet"></i> MAC</th>
                        <th width="10%" class="text-center"><i class="bi bi-wifi"></i> Conexão</th>
                        <th width="10%" class="text-center"><i class="bi bi-check-circle"></i> Status</th>
                        <th width="13%"><i class="bi bi-person-badge"></i> Usuário Hotspot</th>
                        <th width="18%"><i class="bi bi-speedometer2"></i> Tráfego (RX / TX)</th>
                    </tr>
                </thead>
                <tbody>
    `;

    connectedDevices.forEach((device, index) => {
        // Determine connection type icon
        let connectionIcon = 'bi-ethernet';
        let connectionBadge = 'bg-secondary';
        if (device.interface_type === 'WiFi') {
            connectionIcon = 'bi-wifi';
            connectionBadge = 'bg-info';
        } else if (device.interface_type === 'Ethernet') {
            connectionIcon = 'bi-ethernet';
            connectionBadge = 'bg-success';
        }

        // Determine status badge
        const statusBadge = jrcRefActive(device) ?
            '<span class="badge online">Online</span>' :
            '<span class="badge offline">Offline</span>';

        // Display vendor name if available, otherwise use hostname
        const displayName = device.hostname || device.vendor || 'Dispositivo sem nome';

        html += `
            <tr data-mac="${jrcRefValue(device.mac_address)}">
                <td class="text-center">${index + 1}</td>
                <td>
                    <i class="bi bi-pc-display text-primary"></i> <strong>${jrcRefValue(displayName)}</strong>
                    ${device.hostname && device.vendor && device.hostname !== device.vendor ? `<br><small class="text-muted">Hostname: ${jrcRefValue(device.hostname)}</small>` : ''}
                </td>
                <td>${makeIPClickable(device.ip_address)}</td>
                <td><code>${jrcRefValue(device.mac_address)}</code></td>
                <td class="text-center">
                    <span class="badge ${connectionBadge}">
                        <i class="${connectionIcon}"></i> ${jrcRefValue(device.interface_type)}
                    </span>
                </td>
                <td class="text-center">${statusBadge}</td>
                <td class="hotspot-user" data-mac="${jrcRefValue(device.mac_address)}">
                    <span class="text-muted">-</span>
                </td>
                <td class="hotspot-traffic" data-mac="${jrcRefValue(device.mac_address)}">
                    <span class="text-muted">-</span>
                </td>
            </tr>
        `;
    });

    html += `
                </tbody>
            </table>
        </div>
    `;

    return html;
}

